def countStrings(S):
    n = len(S)
    count = 0
    char_count = {}

    # Count the frequency of each character in the string
    for char in S:
        char_count[char] = char_count.get(char, 0) + 1

    # Calculate the number of distinct strings after one swap
    for i in range(n):
        for j in range(i + 1, n):
            if S[i] != S[j]:
                # Swap S[i] and S[j] and count the new string
                new_string = list(S)
                new_string[i], new_string[j] = new_string[j], new_string[i]
                new_string = ''.join(new_string)
                count += 1 if new_string not in char_count else 0

    return count
